// Fixture: QUOTED action ref (legal YAML, common in generated/templated workflows).
var DS_QUALITY_QUOTED = DS_QUALITY_BETA
    .replace("- uses: dart-lang/setup-dart@v1", '- uses: "dart-lang/setup-dart@v1"');

