        lines.push('printf %s ' + dsShq('#!/bin/sh\necho ' + dsShq(opts.managedBanner)) +
            ' > "$d/nodart/dart-sdk/bin/dart"');
        lines.push('chmod +x "$d/nodart/dart-sdk/bin/dart"');
    }
    if (opts.stubCurlFails) {
