        // path (channel_latest cannot resolve) without any real network.
        lines.push('mkdir -p "$d/bin"');
        lines.push('printf %s ' + dsShq('#!/bin/sh\nexit 1') + ' > "$d/bin/curl"');
        lines.push('chmod +x "$d/bin/curl"');
