on:
  workflow_dispatch: {}
permissions:
  contents: read
  pull-requests: read
  actions: read
jobs:
  probe:
    runs-on: ubuntu-24.04
    timeout-minutes: 8
    steps:
      - name: Checkout factory (engine)
        uses: actions/checkout@v7
        with:
          repository: IstiN/dmtools-agents
