    test('summary output contract: exactly one toolchain line when pinned and matching', function () {
        var r = dsRunRaw('summary', {
            qualityYml: DS_QUALITY_PIN_3135,
            managedBanner: 'Dart SDK version: 3.13.5 (stable) on "linux_x64"',
            pubspec: true
        });
