97:    done <<EOF
98:$(awk -v sq="'" '
99:  # Comment lines never contribute — neither a commented-out step
100:  # ("# - uses: dart-lang/setup-dart@v1") nor a stale "# channel: beta" note.
101:  inb && /^[[:space:]]*#/ { next }
102:  # The step marker must be a live list item ("  - uses: …"), optionally with
103:  # a QUOTED action ref (uses: "dart-lang/setup-dart@v1" — legal YAML, common
104:  # in generated/templated workflows).
105:  /^[[:space:]]*-[[:space:]]*uses:[[:space:]]*"?(dart-lang\/setup-dart)/ { inb = 1; print "step=1"; next }
