127:        // how the sandbox can observe WHICH dirs the script put on PATH for
128:        // the leg session — the only observable for the degraded-branch lie.
129:        // trailTarget may reference the sandbox dir as $d — expanded by the
130:        // wrapper shell (double-quoted), NOT by dsShq.
131:        lines.push('touch /tmp/_registered_paths');
132:        lines.push('before=$(wc -l < /tmp/_registered_paths)');
