}

function fetchToolchainLines(workingDir) {
   var script = resolveDartScriptPath(workingDir);
   if (!script) return null;
   var out = null;
   try {
       var args = { command: 'bash ' + script + ' summary' };
       if (workingDir) args.workingDirectory = workingDir;
       out = cli_execute_command(args);
   } catch (e) {
       console.warn('toolchainSummary: dart.sh summary failed (non-fatal):', e && e.message ? e.message : String(e));
       return null;
   }
   var lines = String(out || '').split('\n');
   var picked = [];
   for (var i = 0; i < lines.length; i++) {
       var line = lines[i].replace(/\r$/, '');
       if (line.indexOf('toolchain:') === 0 || (picked.length > 0 && line.indexOf('⚠️') === 0 && line.indexOf('differ from CI') !== -1)) {
           picked.push(line);
           if (picked.length >= 2) break;
