}

function hasToolchainLine(responseText) {
   return String(responseText || '').split('\n').some(... ) — GralJS supports some? Array.prototype.some should exist in GralJS. Use a loop to be safe.
}

function withToolchainLine(responseText, opts) {
   opts = opts || {};
   var text = responseText; // string or null
   if (!text || !String(text).trim()) return responseText;  // nothing to annotate
   if (hasToolchainLine(text)) return responseText;         // already carried
   var lines;
   try { lines = fetchToolchainLines(opts.workingDir); } catch (e) { lines = null; }
