   return String(text).replace(/\s*$/, '') + '\n' + lines.join('\n') + '\n';
}

module.exports = { withToolchainLine: withToolchainLine, fetchToolchainLines: fetchToolchainLines, resolveDartScriptPath: resolveDartScriptPath };
