Helper design (GrAAJS constraints: var, no arrow fns, no template literals, JSON-safe, hoisted requires):

```js
/**
 * Appends the gh-1137 toolchain line to the leg summary (outputs/response.md
 * content) ...
 */
var childProcess? no. Uses cli_execute_command + file_read (global dmtools tools).

function resolveDartScriptPath(workingDir) {
   var candidates = [
       (workingDir ? workingDir + '/' : '') + 'setup/dart.sh',
       (workingDir ? workingDir + '/' : '') + 'agents/setup/dart.sh',
       (workingDir ? workingDir + '/' : '') + 'factory-agents/setup/dart.sh'
   ];
   for (var i = 0; i < candidates.length; i++) {
       var content = null;
       try { content = file_read({ path: candidates[i] }); } catch (e) { content = null; }
       if (content && String(content).indexOf('dart.sh') !== -1) ... hmm — file_read returns content; a match on any content is fine. Simpler: non-null content → exists.
   }
   return null;
}

function fetchToolchainLines(workingDir) {
   var script = resolveDartScriptPath(workingDir);
   if (!script) return null;
   var out = null;
   try {
       var args = { command: 'bash ' + script + ' summary' };
       if (workingDir) args.workingDirectory = workingDir;
       out = cli_execute_command(args);
   } catch (e) {
       console.warn('toolchainSummary: dart.sh summary failed (non-fatal):', e && e.message ? e.message : String(e));
       return null;
   }
   var lines = String(out || '').split('\n');
   var picked = [];
   for (var i = 0; i < lines.length; i++) {
       var line = lines[i].replace(/\r$/, '');
       if (line.indexOf('toolchain:') === 0 || (picked.length > 0 && line.indexOf('⚠️') === 0 && line.indexOf('differ from CI') !== -1)) {
           picked.push(line);
           if (picked.length >= 2) break;
       }
   }
   return picked.length ? picked : null;
}

function hasToolchainLine(responseText) {
   return String(responseText || '').split('\n').some(... ) — GralJS supports some? Array.prototype.some should exist in GralJS. Use a loop to be safe.
}

function withToolchainLine(responseText, opts) {
   opts = opts || {};
   var text = responseText; // string or null
   if (!text || !String(text).trim()) return responseText;  // nothing to annotate
   if (hasToolchainLine(text)) return responseText;         // already carried
   var lines;
   try { lines = fetchToolchainLines(opts.workingDir); } catch (e) { lines = null; }
   if (!lines) return responseText;
   // dart none (non-Dart repo) → no annotation noise on JS/Kotlin repos
   var head = lines[0];
   if (head.indexOf('toolchain: dart none') === 0) return responseText;
   return String(text).replace(/\s*$/, '') + '\n' + lines.join('\n') + '\n';
}

module.exports = { withToolchainLine: withToolchainLine, fetchToolchainLines: fetchToolchainLines, resolveDartScriptPath: resolveDartScriptPath };
``

